function sortThreeKinds(nums: number[]): void {
  const count = [0, 0, 0];
  for (const x of nums) count[x]++;
  let i = 0;
  for (let v = 0; v < 3; v++) {
    for (let c = 0; c < count[v]; c++) nums[i++] = v;
  }
}

